import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline


_cuda_src = r"""
#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <cuda.h>
#include <cuda_runtime.h>

__global__ void conv2d_kernel(
    const float* __restrict__ x,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ out,
    int N,
    int IC,
    int IH,
    int IW,
    int OC,
    int OH,
    int OW,
    int KH,
    int KW,
    int stride_h,
    int stride_w,
    int pad_h,
    int pad_w,
    int dil_h,
    int dil_w,
    int use_shared
) {
    constexpr int BW = 16;
    constexpr int BOC = 8;

    const int tx = threadIdx.x;
    const int ty = threadIdx.y;
    const int ow = blockIdx.x * BW + tx;
    const int oh = blockIdx.y;

    const int oc_tiles = (OC + BOC - 1) / BOC;
    const int oc_tile = blockIdx.z % oc_tiles;
    const int n = blockIdx.z / oc_tiles;
    const int oc = oc_tile * BOC + ty;

    const int effective_h = (KH - 1) * dil_h + 1;
    const int effective_w = (KW - 1) * dil_w + 1;
    const int tile_h = effective_h;
    const int tile_w = (BW - 1) * stride_w + effective_w;

    extern __shared__ float smem[];

    const int ih_base = oh * stride_h - pad_h;
    const int iw_base = blockIdx.x * BW * stride_w - pad_w;

    if (use_shared) {
        const int tid = ty * blockDim.x + tx;
        const int threads = blockDim.x * blockDim.y;
        const int tile_elems = IC * tile_h * tile_w;

        for (int idx = tid; idx < tile_elems; idx += threads) {
            const int iw_local = idx % tile_w;
            const int tmp = idx / tile_w;
            const int ih_local = tmp % tile_h;
            const int ic = tmp / tile_h;

            const int ih = ih_base + ih_local;
            const int iw = iw_base + iw_local;

            float value = 0.0f;
            if (ih >= 0 && ih < IH && iw >= 0 && iw < IW) {
                const int x_offset =
                    ((n * IC + ic) * IH + ih) * IW + iw;
                value = x[x_offset];
            }

            smem[idx] = value;
        }
        __syncthreads();
    }

    if (n >= N || oh >= OH || ow >= OW || oc >= OC) {
        return;
    }

    float acc = bias != nullptr ? bias[oc] : 0.0f;

    for (int ic = 0; ic < IC; ++ic) {
        for (int kh = 0; kh < KH; ++kh) {
            const int ih = ih_base + kh * dil_h;

            for (int kw = 0; kw < KW; ++kw) {
                const int iw = iw_base + tx * stride_w + kw * dil_w;

                float input_value;
                if (use_shared) {
                    const int ih_local = kh * dil_h;
                    const int iw_local = tx * stride_w + kw * dil_w;
                    const int smem_offset =
                        (ic * tile_h + ih_local) * tile_w + iw_local;
                    input_value = smem[smem_offset];
                } else {
                    input_value = 0.0f;
                    if (ih >= 0 && ih < IH && iw >= 0 && iw < IW) {
                        const int x_offset =
                            ((n * IC + ic) * IH + ih) * IW + iw;
                        input_value = x[x_offset];
                    }
                }

                const int weight_offset =
                    ((oc * IC + ic) * KH + kh) * KW + kw;

                acc += input_value * weight[weight_offset];
            }
        }
    }

    const int out_offset =
        ((n * OC + oc) * OH + oh) * OW + ow;
    out[out_offset] = acc;
}

torch::Tensor conv2d_cuda(
    torch::Tensor x,
    torch::Tensor weight,
    c10::optional<torch::Tensor> bias,
    int64_t stride_h,
    int64_t stride_w,
    int64_t pad_h,
    int64_t pad_w,
    int64_t dil_h,
    int64_t dil_w
) {
    TORCH_CHECK(x.is_cuda(), "input must be CUDA");
    TORCH_CHECK(weight.is_cuda(), "weight must be CUDA");
    TORCH_CHECK(x.scalar_type() == torch::kFloat32, "input must be float32");
    TORCH_CHECK(weight.scalar_type() == torch::kFloat32, "weight must be float32");
    TORCH_CHECK(x.dim() == 4, "input must have shape NCHW");
    TORCH_CHECK(weight.dim() == 4, "weight must have shape OIHW");
    TORCH_CHECK(x.is_contiguous(), "input must be contiguous");
    TORCH_CHECK(weight.is_contiguous(), "weight must be contiguous");

    const auto N = static_cast<int>(x.size(0));
    const auto IC = static_cast<int>(x.size(1));
    const auto IH = static_cast<int>(x.size(2));
    const auto IW = static_cast<int>(x.size(3));

    const auto OC = static_cast<int>(weight.size(0));
    const auto WIC = static_cast<int>(weight.size(1));
    const auto KH = static_cast<int>(weight.size(2));
    const auto KW = static_cast<int>(weight.size(3));

    TORCH_CHECK(IC == WIC, "input and weight channel dimensions must match");

    if (bias.has_value()) {
        TORCH_CHECK(bias->is_cuda(), "bias must be CUDA");
        TORCH_CHECK(bias->scalar_type() == torch::kFloat32, "bias must be float32");
        TORCH_CHECK(bias->dim() == 1 && bias->size(0) == OC, "invalid bias shape");
        TORCH_CHECK(bias->is_contiguous(), "bias must be contiguous");
    }

    const int effective_h = (KH - 1) * static_cast<int>(dil_h) + 1;
    const int effective_w = (KW - 1) * static_cast<int>(dil_w) + 1;

    const int OH =
        (IH + 2 * static_cast<int>(pad_h) -
         effective_h) / static_cast<int>(stride_h) + 1;
    const int OW =
        (IW + 2 * static_cast<int>(pad_w) -
         effective_w) / static_cast<int>(stride_w) + 1;

    TORCH_CHECK(OH >= 0 && OW >= 0, "invalid convolution output dimensions");

    auto out = torch::empty(
        {N, OC, OH, OW},
        x.options()
    );

    constexpr int BW = 16;
    constexpr int BOC = 8;

    const int tile_h = effective_h;
    const int tile_w =
        (BW - 1) * static_cast<int>(stride_w) + effective_w;

    const size_t shared_bytes =
        static_cast<size_t>(IC) * tile_h * tile_w * sizeof(float);

    const size_t shared_limit = 48 * 1024;
    const int use_shared = shared_bytes <= shared_limit ? 1 : 0;

    dim3 block(BW, BOC);
    dim3 grid(
        (OW + BW - 1) / BW,
        OH,
        N * ((OC + BOC - 1) / BOC)
    );

    const float* bias_ptr = nullptr;
    if (bias.has_value()) {
        bias_ptr = bias->data_ptr<float>();
    }

    auto stream = at::cuda::getCurrentCUDAStream(x.device().index()).stream();

    conv2d_kernel<<<
        grid,
        block,
        use_shared ? shared_bytes : 0,
        stream
    >>>(
        x.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias_ptr,
        out.data_ptr<float>(),
        N,
        IC,
        IH,
        IW,
        OC,
        OH,
        OW,
        KH,
        KW,
        static_cast<int>(stride_h),
        static_cast<int>(stride_w),
        static_cast<int>(pad_h),
        static_cast<int>(pad_w),
        static_cast<int>(dil_h),
        static_cast<int>(dil_w),
        use_shared
    );

    C10_CUDA_KERNEL_LAUNCH_CHECK();
    return out;
}

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("conv2d", &conv2d_cuda, "Custom CUDA 2D convolution");
}
"""

_conv2d_ext = load_inline(
    name="custom_conv2d_cuda_ext",
    cpp_sources="",
    cuda_sources=_cuda_src,
    functions=None,
    extra_cuda_cflags=["-O3"],
    with_cuda=True,
    verbose=False,
)


class ModelNew(nn.Module):
    def __init__(
        self,
        in_channels: int,
        out_channels: int,
        kernel_size: tuple,
        stride: int = 1,
        padding: tuple = (0, 0),
        dilation: tuple = (1, 1),
        bias: bool = False,
    ):
        super().__init__()

        self.conv2d = nn.Conv2d(
            in_channels,
            out_channels,
            kernel_size,
            stride=stride,
            padding=padding,
            dilation=dilation,
            bias=bias,
        )

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return _conv2d_ext.conv2d(
            x.contiguous(),
            self.conv2d.weight.contiguous(),
            self.conv2d.bias.contiguous() if self.conv2d.bias is not None else None,
            self.conv2d.stride[0],
            self.conv2d.stride[1],
            self.conv2d.padding[0],
            self.conv2d.padding[1],
            self.conv2d.dilation[0],
            self.conv2d.dilation[1],
        )

